pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead zones" (small residuals that are unlikely to fit future items).
    // Thresholds around 10-20 are critical given item size range.
    if post_residual > 0 && post_residual < 15 {
        score += 45.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // 2. Lookahead: Prefer placing items into bins that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // 3. Global State: If we have many open bins, prioritize tightening existing ones.
    // If we have few open bins, prioritize creating new ones if the fit is poor.
    let bin_density = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (open_bins_count as f64) * 2.5 * (1.0 - bin_density);

    // 4. Fitting Pressure: If this is the last chance to fit the item in an existing bin,
    // lower the score to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Logic: Only open a new bin if the fit is truly suboptimal.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by progress to be more conservative late-game.
        score = 40.0 + (progress * 20.0);

        // If existing bins are very empty on average, don't open a new one.
        if mean_residual > 50.0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps (Best Fit principle)
    let mut score = post * post * 0.01;

    // Non-linear coupling: As the stream progresses, prioritize tighter packing (lower residual)
    // to avoid stranded small items at the end.
    score += (1.0 - progress) * (bin_capacity as f64 - post) * 0.5;

    // Lookahead logic: If the next item is large, avoid creating small residuals that are unusable.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 2.0;
        }
    }

    // Penalty for opening new bins: Only open a new bin if the current fit is extremely poor
    // relative to the mean residual of existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 15.0 + (mean_residual * 0.5);
        } else {
            score -= 5.0; // Essential to open a new bin if nothing fits
        }
    }

    // Favor bins that result in a residual close to the mean, promoting uniformity
    score += (post - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score to select the best bin.
    // Logic: 
    // 1. Prioritize Best-Fit (minimizing post_residual).
    // 2. Penalize new bin creation unless it's strictly necessary or beneficial for future packing.
    // 3. Utilize lookahead (next_item_size) to avoid creating "orphaned" residuals.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a new bin:
    // We only open a new bin if the fit in existing bins is poor (high post_residual).
    if is_new_bin {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Base penalty for opening a new bin is the average space we would waste in current bins
        score = mean_residual * 1.5;
    }

    // Lookahead logic: 
    // If the next item fits into the current post_residual, we reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // strongly prioritize filling it to avoid forcing a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Dynamic time horizon adjustment: 
    // As the stream progresses, prioritize closing bins (lower mean_residual).
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress);

    // Final penalty for leaving small, unusable gaps (e.g., < 10) that cannot fit any item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    score
}

