        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 150.0 - mean_residual;
        } else {
            // If no bins fit, this is a forced new bin, set to neutral
            score = 50.0;
        }
    }

    // 4. Fragmentation avoidance: If we are near the end of the stream, 
    // prioritize packing tighter to minimize residual waste.
    let progress = step_index as f64 / total_items as f64;
