        score += (post_residual as f64) * 0.5;
    }

    // 5. Mean residual balancing: Penalize placing into bins that are already 
    // significantly more empty than the average, to preserve them for larger items.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 5.0;
    }

    score
}

