pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely unusable.
    // We penalize these gaps heavily to encourage "perfect" fits (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // we reward this bin heavily to keep the bin useful for the immediate future.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - (diff / 100.0));
    }

    // 3. Open Bin Pressure: If we have many open bins, we must prioritize filling them
    // to avoid leaving them underutilized. If we have few, we can be more selective.
    score += (open_bins_count as f64) * 2.5;

    // 4. New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the penalty for using an existing bin is extremely high.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, but decreases as the 
        // number of fitting bins decreases (i.e., we are forced to open a new one).
        score = 85.0 - (fitting_bins_count as f64 * 10.0);
    }

    // 5. Mean residual balancing: Penalize placing in bins that are significantly
    // emptier than the average, as this keeps the "mean_residual" high and 
    // reduces our flexibility for future large items.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if fitting bins are scarce
    let mut score = post_residual as f64;

    if is_new_bin {
        // New bin penalty increases as the stream progresses, but is mitigated 
        // if we are running out of good fitting options.
        score += (1.0 - progress) * 50.0 + (fitting_bins_count as f64 * 10.0);
    } else {
        // Best Fit Decreasing logic: Favor bins that result in smaller residuals.
        // Penalty for creating "dead space" (e.g., residual < 10) that is hard to fill.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 + progress);
        }

        // Lookahead coupling: If the next item is large, penalize bins that 
        // leave little room after the current placement.
        if next_item_size > 50 && post_residual < next_item_size {
            score += 15.0;
        }

        // Encourage keeping residuals close to the global mean to maintain bin uniformity
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We favor smaller post_residuals (the standard Best-Fit logic).

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual, 
    // heavily incentivize this bin (a "combo" placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // Reward: Subtract a value based on how perfectly it matches.
        score -= (100.0 - gap as f64) * 2.5;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current 
    // fits are extremely poor (i.e., they create large unusable dead space).
    if bin_residual == bin_capacity {
        // If we have fitting bins, only open a new one if our current open bins 
        // are all "bad" (post_residual > 30).
        if fitting_bins_count > 0 {
            score += 45.0; 
        }
    }

    // 4. Fragmentation Avoidance: If post_residual is small but > 0, it is often 
    // "dead space" (too small for most incoming items). Penalize these "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global Efficiency: If the bin is currently much emptier than the average, 
    // prioritize filling it to keep the average residual consistent.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Progression Normalization: As the stream nears the end, become more 
    // aggressive about closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}
